def carve(size, target, direction, start=None, max_steps=1_000_000):
    if size < 3:
        raise ValueError("the grid needs an interior")
    if not 0 < target < 1:
        raise ValueError("target must be a fraction strictly between 0 and 1")
    interior = (size - 2) ** 2
    wanted = int(target * interior)
    grid = [[1] * size for _ in range(size)]
    x, y = start if start is not None else (size // 2, size // 2)
    if not (1 <= x <= size - 2 and 1 <= y <= size - 2):
        raise ValueError("the start must be inside the interior")
    grid[y][x] = 0
    carved = 1
    steps = 0
    while carved < wanted and steps < max_steps:
        steps += 1
        dx, dy = direction()
        nx, ny = x + dx, y + dy
        if not (1 <= nx <= size - 2 and 1 <= ny <= size - 2):
            continue
        x, y = nx, ny
        if grid[y][x] == 1:
            grid[y][x] = 0
            carved += 1
    return {"grid": grid, "carved": carved, "steps": steps,
            "reached_target": carved >= wanted}
